generationPayload.mermaid:
flowchart TD;
    A(["Start"]);
    B["Create an empty list for daily visits"];
    C["Initialize the counter to zero"];
    D{"Counter < 7?"};
    E[/"Read the day's number of visits"/];
    F["Add the number to the list"];
    G["Increment the counter"];
    H["Correct Friday's number of visits"];
    I[/"Display the corrected list"/];
    Z(["End"]);

    A --> B;
    B --> C;
    C --> D;
    D -- "Yes" --> E;
    E --> F;
    F --> G;
    G --> D;
    D -- "No" --> H;
    H --> I;
    I --> Z;

